-- ─────────────────────────────────────────────────────────────────────
-- PERO-J local development seed (issue #1016)
-- Pre-seeds test markets (ABI metadata) and simulated user accounts
-- (sample decoded events) so the frontend has data on first run.
-- Idempotent: contracts are upserted; events are inserted only when the
-- events table is empty, so re-running `docker compose up` does not
-- duplicate seed rows.
--
-- Applied by the `seed` one-shot service in docker-compose.yml.
-- ─────────────────────────────────────────────────────────────────────
BEGIN;

-- ── Test markets (ABI metadata) ───────────────────────────────────────
INSERT INTO contracts (id, name, description, functions, registered_by) VALUES ('CDLZFC3SYJYDZT7K67VZ75HPJVIEUVNIXF47ZG2FB2RMQQVU2HHGCYSC', 'StellarSwap', 'Automated market-maker DEX on Stellar testnet (Tranche 2 integration fixture)', '[{"name":"swap","description":"Swap an exact amount of token_in for at least min_out of token_out","params":[{"name":"caller","kind":"address"},{"name":"token_in","kind":"address"},{"name":"token_out","kind":"address"},{"name":"amount_in","kind":"i128"},{"name":"min_out","kind":"i128"}]},{"name":"add_liquidity","description":"Deposit token_a and token_b into a liquidity pool and receive LP tokens","params":[{"name":"caller","kind":"address"},{"name":"token_a","kind":"address"},{"name":"token_b","kind":"address"},{"name":"amount_a","kind":"i128"},{"name":"amount_b","kind":"i128"},{"name":"min_lp_out","kind":"i128"}]},{"name":"remove_liquidity","description":"Burn LP tokens and receive back token_a and token_b","params":[{"name":"caller","kind":"address"},{"name":"lp_amount","kind":"i128"},{"name":"min_a_out","kind":"i128"},{"name":"min_b_out","kind":"i128"}]},{"name":"get_price","description":"Return the current spot price of token_in denominated in token_out","params":[{"name":"token_in","kind":"address"},{"name":"token_out","kind":"address"}]}]'::jsonb, 'seed') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, functions = EXCLUDED.functions;
INSERT INTO contracts (id, name, description, functions, registered_by) VALUES ('CBDIZJSO3SZGBYABF4RBE75QNRYNXP5KOGP7GF23JDZUOBAVNISTL52', 'Blend', 'Lending/borrowing protocol on Stellar testnet (Tranche 2 integration fixture)', '[{"name":"supply","description":"Supply an asset to the Blend pool and receive b-tokens representing the deposit","params":[{"name":"caller","kind":"address"},{"name":"asset","kind":"address"},{"name":"amount","kind":"i128"}]},{"name":"withdraw","description":"Withdraw a previously supplied asset by burning the corresponding b-tokens","params":[{"name":"caller","kind":"address"},{"name":"asset","kind":"address"},{"name":"b_tokens","kind":"i128"}]},{"name":"borrow","description":"Borrow an asset against deposited collateral","params":[{"name":"caller","kind":"address"},{"name":"asset","kind":"address"},{"name":"amount","kind":"i128"}]},{"name":"repay","description":"Repay a previously borrowed amount and reduce the debt position","params":[{"name":"caller","kind":"address"},{"name":"asset","kind":"address"},{"name":"amount","kind":"i128"}]},{"name":"liquidate","description":"Liquidate an undercollateralised borrower position and claim the collateral discount","params":[{"name":"liquidator","kind":"address"},{"name":"borrower","kind":"address"},{"name":"asset","kind":"address"},{"name":"amount","kind":"i128"}]},{"name":"get_position","description":"Return the current supply and borrow balance for a user","params":[{"name":"user","kind":"address"},{"name":"asset","kind":"address"}]},{"name":"stake","description":"Stake tokens into the Blend backstop or staking module","params":[{"name":"from","kind":"address"},{"name":"amount","kind":"i128"},{"name":"token","kind":"address"}]},{"name":"unstake","description":"Unstake tokens previously staked in the Blend backstop or staking module","params":[{"name":"from","kind":"address"},{"name":"amount","kind":"i128"},{"name":"token","kind":"address"}]},{"name":"deposit","description":"Deposit tokens into the protocol","params":[{"name":"from","kind":"address"},{"name":"amount","kind":"i128"},{"name":"token","kind":"address"}]}]'::jsonb, 'seed') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, functions = EXCLUDED.functions;
INSERT INTO contracts (id, name, description, functions, registered_by) VALUES ('CAIN2V776IOGWBS75BVEY7BR3RSVEPVXQFTTIEPLSRLHJICSPCZT47KZ', 'Phoenix', 'Constant-product DEX on Stellar testnet (Tranche 2 integration fixture)', '[{"name":"swap","description":"Swap an exact amount of token_in for at least min_out of token_out in a Phoenix pool","params":[{"name":"caller","kind":"address"},{"name":"token_in","kind":"address"},{"name":"token_out","kind":"address"},{"name":"amount_in","kind":"i128"},{"name":"min_out","kind":"i128"}]},{"name":"add_liquidity","description":"Deposit token_a and token_b into a Phoenix pool and receive LP tokens","params":[{"name":"caller","kind":"address"},{"name":"token_a","kind":"address"},{"name":"token_b","kind":"address"},{"name":"amount_a","kind":"i128"},{"name":"amount_b","kind":"i128"},{"name":"min_lp_out","kind":"i128"}]},{"name":"remove_liquidity","description":"Burn LP tokens and withdraw the underlying token_a and token_b from a Phoenix pool","params":[{"name":"caller","kind":"address"},{"name":"lp_amount","kind":"i128"},{"name":"min_a_out","kind":"i128"},{"name":"min_b_out","kind":"i128"}]},{"name":"get_reserves","description":"Return the current token_a and token_b reserves of the Phoenix pool","params":[{"name":"token_a","kind":"address"},{"name":"token_b","kind":"address"}]}]'::jsonb, 'seed') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, functions = EXCLUDED.functions;

